// Hub's mark, inline: a central node (accent) with three spokes to satellite nodes (text color). The same
// geometry as web/public/icon.svg (generated by scripts/gen-icons.ts) without the tile, cropped to the
// mark. Decorative: the "Hub" wordmark next to it carries the name.
export function HubMark(props: { size?: number; class?: string }) {
  const size = () => props.size ?? 18
  return (
    <svg
      class={`hub-mark${props.class ? ` ${props.class}` : ""}`}
      viewBox="72 51 368 368"
      width={size()}
      height={size()}
      aria-hidden="true"
    >
      <g transform="translate(0 20.7)">
        <g stroke="currentColor" stroke-width="22" stroke-linecap="round">
          <line x1="256" y1="256" x2="256" y2="90" />
          <line x1="256" y1="256" x2="399.8" y2="339" />
          <line x1="256" y1="256" x2="112.2" y2="339" />
        </g>
        <g fill="currentColor">
          <circle cx="256" cy="90" r="40" />
          <circle cx="399.8" cy="339" r="40" />
          <circle cx="112.2" cy="339" r="40" />
        </g>
        <circle class="hub-mark-gap" cx="256" cy="256" r="71" />
        <circle class="hub-mark-hub" cx="256" cy="256" r="60" />
      </g>
    </svg>
  )
}
